(function(root){root.SUPPORT_TOPICS=[{id:"vault",en:"Bazinet Vault",fr:"Bazinet Vault"},{id:"horaire",en:"Horaire CVM",fr:"Horaire CVM"},{id:"aim",en:"Aim Trainer",fr:"Entraîneur de visée"},{id:"account",en:"Account and sign-in",fr:"Compte et connexion"},{id:"billing",en:"Pro and billing",fr:"Pro et facturation"},{id:"privacy",en:"Privacy and security",fr:"Confidentialité et sécurité"}];root.SUPPORT_ARTICLES=[{id:"vault-start",topic:"vault",popular:true,keywords:{en:"create new vault set up begin first time sign up register how to start using",fr:"créer nouveau coffre commencer inscription première fois utiliser démarrer"},title:{en:"Getting started with Bazinet Vault",fr:"Premiers pas avec Bazinet Vault"},body:[{p:{en:"Bazinet Vault stores your passwords, notes and files encrypted on your own device. You need a Bazinet account and a master password.",fr:"Bazinet Vault conserve vos mots de passe, notes et fichiers chiffrés sur votre propre appareil. Il vous faut un compte Bazinet et un mot de passe maître."}},{steps:{en:["Create a Bazinet account and confirm your email.","Open the vault and choose a master password. It encrypts everything, and nobody else ever receives it.","Save a recovery key from the vault menu and keep it somewhere safe.","Add your first logins, or install the browser extension to save them as you sign in."],fr:["Créez un compte Bazinet et confirmez votre courriel.","Ouvrez le coffre-fort et choisissez un mot de passe maître. Il chiffre tout, et personne d'autre ne le reçoit jamais.","Enregistrez une clé de récupération à partir du menu du coffre-fort et gardez-la en lieu sûr.","Ajoutez vos premiers identifiants, ou installez l'extension de navigateur pour les enregistrer quand vous vous connectez."]}},{link:["/app",{en:"Open the vault",fr:"Ouvrir le coffre-fort"}]}]},{id:"master-password",topic:"vault",popular:true,keywords:{en:"forgot lost reset recover master password unlock recovery key locked out",fr:"oublié perdu réinitialiser récupérer mot de passe maître déverrouiller clé de récupération bloqué"},title:{en:"I forgot my master password",fr:"J'ai oublié mon mot de passe maître"},body:[{p:{en:"Your vault is encrypted with your master password on your device. We never receive it, so we cannot show it to you or reset it — and nobody at Bazinet can open your vault.",fr:"Votre coffre-fort est chiffré avec votre mot de passe maître sur votre appareil. Nous ne le recevons jamais : nous ne pouvons donc ni vous le montrer ni le réinitialiser, et personne chez Bazinet ne peut ouvrir votre coffre-fort."}},{steps:{en:["On the unlock screen, choose “Use a recovery key instead”.","Enter the recovery key you saved.","Choose a new master password."],fr:["À l'écran de déverrouillage, choisissez « Utiliser plutôt une clé de récupération ».","Entrez la clé de récupération que vous avez enregistrée.","Choisissez un nouveau mot de passe maître."]}},{note:{en:"Without a recovery key, a forgotten master password means the vault cannot be decrypted by anyone. Your account password is separate: resetting it does not change your master password.",fr:"Sans clé de récupération, un mot de passe maître oublié signifie que personne ne peut déchiffrer le coffre-fort. Le mot de passe de votre compte est distinct : le réinitialiser ne change pas votre mot de passe maître."}}]},{id:"extension",topic:"vault",keywords:{en:"chrome extension install autofill fill passwords browser update required not working",fr:"extension chrome installer remplissage automatique navigateur mise à jour requise ne fonctionne pas"},title:{en:"Installing the browser extension",fr:"Installer l'extension de navigateur"},body:[{p:{en:"The extension fills and saves logins as you browse. It refuses to fill a site that only looks like the one you saved, which is how most phishing works.",fr:"L'extension remplit et enregistre vos identifiants pendant que vous naviguez. Elle refuse de remplir un site qui ressemble seulement à celui que vous avez enregistré, ce qui est le principe de la plupart des hameçonnages."}},{steps:{en:["Get it from the Chrome Web Store.","Click the Bazinet icon in your toolbar and sign in to your Bazinet account.","Unlock with your master password."],fr:["Obtenez-la dans le Chrome Web Store.","Cliquez sur l'icône Bazinet dans votre barre d'outils et connectez-vous à votre compte Bazinet.","Déverrouillez avec votre mot de passe maître."]}},{note:{en:"If the extension says an update is required, update it from chrome://extensions, then open it again.",fr:"Si l'extension indique qu'une mise à jour est requise, mettez-la à jour à partir de chrome://extensions, puis rouvrez-la."}},{link:["/extension",{en:"About the extension",fr:"À propos de l'extension"}]}]},{id:"mac-app",topic:"vault",keywords:{en:"mac app desktop download macos apple silicon install horaire app windows",fr:"application mac bureau télécharger macos puce apple installer application horaire windows"},title:{en:"The Mac apps",fr:"Les applications Mac"},body:[{p:{en:"Bazinet Vault and Horaire CVM each have a Mac app. The Vault app keeps your vault apart from your browser and its extensions, with your session in the macOS Keychain. Both run on Apple Silicon Macs with macOS 10.15 or later, and update themselves.",fr:"Bazinet Vault et Horaire CVM ont chacun une application Mac. L'application Vault garde votre coffre-fort à l'écart du navigateur et de ses extensions, avec votre session dans le trousseau de macOS. Les deux fonctionnent sur les Mac à puce Apple avec macOS 10.15 ou plus récent, et se mettent à jour d'elles-mêmes."}},{steps:{en:["Download the app from the Download page.","Open the file and move the app to Applications.","Sign in with your Bazinet account (and, for the vault, unlock with your master password)."],fr:["Téléchargez l'application à partir de la page Téléchargement.","Ouvrez le fichier et déplacez l'application dans Applications.","Connectez-vous avec votre compte Bazinet (et, pour le coffre-fort, déverrouillez avec votre mot de passe maître)."]}},{note:{en:"There is no Windows or Linux app for the vault or Horaire: on those, use them in the browser. The Aim Trainer is the Windows app.",fr:"Il n'y a pas d'application Windows ou Linux pour le coffre-fort ni pour Horaire : utilisez-les dans le navigateur. L'entraîneur de visée est l'application Windows."}},{link:["/download",{en:"Download for Mac",fr:"Télécharger pour Mac"}]}]},{id:"horaire-import",topic:"horaire",popular:true,keywords:{en:"import schedule pdf omnivox timetable horaire de cours setup agenda",fr:"importer horaire pdf omnivox horaire de cours agenda configurer"},title:{en:"Importing your schedule into Horaire",fr:"Importer votre horaire dans Horaire"},body:[{p:{en:"Horaire builds your agenda from the schedule PDF that Omnivox gives you. The file is read on your device and never sent to us.",fr:"Horaire construit votre agenda à partir du PDF d'horaire fourni par Omnivox. Le fichier est lu sur votre appareil et ne nous est jamais envoyé."}},{steps:{en:["In Omnivox, open Horaire de cours.","Choose the session, then Consulter mon horaire.","Open Version imprimable, choose “Horaire de la session en version abrégée” (the full-format one can't be read), then click Visualiser and save the PDF.","In Horaire, drop the PDF on the import screen, then check the first and last day of the term."],fr:["Dans Omnivox, ouvrez Horaire de cours.","Choisissez la session, puis Consulter mon horaire.","Ouvrez la Version imprimable, choisissez « Horaire de la session en version abrégée » (le plein format ne peut pas être lu), puis cliquez sur Visualiser et enregistrez le PDF.","Dans Horaire, déposez le PDF à l'écran d'importation, puis vérifiez le premier et le dernier jour de la session."]}},{note:{en:"For Cégep du Vieux Montréal terms, the holidays and pedagogical days are filled in from the official calendar. You can change them any time in Settings.",fr:"Pour les sessions du Cégep du Vieux Montréal, les congés et les journées pédagogiques sont remplis à partir du calendrier officiel. Vous pouvez les modifier en tout temps dans les réglages."}},{link:["/horaire",{en:"Open Horaire",fr:"Ouvrir Horaire"}]}]},{id:"horaire-omnivox",topic:"horaire",popular:true,keywords:{en:"connect omnivox phone password DA sign in code email lea mio sync",fr:"connecter omnivox téléphone mot de passe DA code courriel lea mio synchronisation"},title:{en:"Connecting Omnivox to Horaire",fr:"Connecter Omnivox à Horaire"},body:[{p:{en:"On a computer, the Bazinet browser extension reads LÉA and Mio through the Omnivox session you are already signed in to; your Omnivox password is never involved. On a phone, where extensions don't exist, you can connect Omnivox in Horaire's settings (Pro).",fr:"Sur un ordinateur, l'extension de navigateur Bazinet lit LÉA et Mio avec la session Omnivox où vous êtes déjà connecté; votre mot de passe Omnivox n'est jamais utilisé. Sur un téléphone, où les extensions n'existent pas, vous pouvez connecter Omnivox dans les réglages d'Horaire (Pro)."}},{steps:{en:["Open Horaire, then Settings, then Connect Omnivox.","Enter your DA and your Omnivox password, and accept the terms shown.","The first time, Omnivox emails you a code: enter it once, and this device is remembered."],fr:["Ouvrez Horaire, puis les réglages, puis Connecter Omnivox.","Entrez votre numéro de DA et votre mot de passe Omnivox, et acceptez les conditions affichées.","La première fois, Omnivox vous envoie un code par courriel : entrez-le une fois, et cet appareil sera mémorisé."]}},{note:{en:"Your Omnivox password is encrypted on your device with your account key. It is decrypted only for a sign-in, used, and not kept. If Omnivox later ends the session, Horaire never sends a code by itself: it asks you to sign in again when you're ready.",fr:"Votre mot de passe Omnivox est chiffré sur votre appareil avec la clé de votre compte. Il n'est déchiffré que pour une connexion, utilisé, puis non conservé. Si Omnivox met fin à la session plus tard, Horaire n'envoie jamais de code de lui-même : il vous demande de vous reconnecter quand vous êtes prêt."}}]},{id:"horaire-plans",topic:"horaire",keywords:{en:"plan de cours evaluation dates exams assignments wrong dates course outline",fr:"plans de cours dates d'évaluation examens travaux mauvaises dates"},title:{en:"Getting evaluation dates from your plans de cours",fr:"Obtenir les dates d'évaluation de vos plans de cours"},body:[{p:{en:"Horaire can read the plans de cours posted on LÉA and place each exam and assignment on the day your course meets (Pro). Nothing is added until you confirm it.",fr:"Horaire peut lire les plans de cours publiés sur LÉA et placer chaque examen et travail le jour où votre cours a lieu (Pro). Rien n'est ajouté avant que vous le confirmiez."}},{steps:{en:["In Horaire, open Settings, then Plans de cours.","Choose “Get my plans de cours from Omnivox”.","Review the dates found, untick anything that doesn't apply, then add the rest."],fr:["Dans Horaire, ouvrez les réglages, puis Plans de cours.","Choisissez « Récupérer mes plans de cours depuis Omnivox ».","Vérifiez les dates trouvées, décochez ce qui ne s'applique pas, puis ajoutez le reste."]}},{note:{en:"Already answered a plan and want to see it again? Choose “Review them again”. If a date looks wrong, open a request here and say which course.",fr:"Vous avez déjà répondu pour un plan et voulez le revoir? Choisissez « Les revoir ». Si une date semble fausse, ouvrez une demande ici en indiquant le cours."}}]},{id:"horaire-mio",topic:"horaire",keywords:{en:"mio messages not loading inbox error",fr:"mio messages ne se chargent pas boîte de réception erreur"},title:{en:"Mio messages don't load",fr:"Les messages Mio ne se chargent pas"},body:[{p:{en:"Mio in Horaire is a Pro feature. It is read through the browser extension when it can, and otherwise through your Omnivox connection.",fr:"Mio dans Horaire est une fonction Pro. Il est lu avec l'extension de navigateur quand c'est possible, sinon avec votre connexion Omnivox."}},{steps:{en:["If you use the extension, open Omnivox once in the same browser so it knows where your school account is.","If you connected Omnivox, open Horaire's settings and check that it says connected. If it asks you to sign in to Omnivox again, choose “Sign in now”; for any other error, choose “Try again”.","Still stuck? Open a request here: the message on screen, even a short code in brackets, tells us which step failed."],fr:["Si vous utilisez l'extension, ouvrez Omnivox une fois dans le même navigateur pour qu'elle sache où se trouve votre compte scolaire.","Si vous avez connecté Omnivox, ouvrez les réglages d'Horaire et vérifiez qu'il est indiqué comme connecté. S'il vous demande de vous reconnecter à Omnivox, choisissez « Me connecter maintenant »; pour toute autre erreur, choisissez « Réessayer ».","Toujours bloqué? Ouvrez une demande ici : le message à l'écran, même un court code entre parenthèses, nous indique quelle étape a échoué."]}}]},{id:"aim-safe",topic:"aim",keywords:{en:"banned ban safe valorant vanguard allowed rules snap tap riot",fr:"banni bannissement sécuritaire valorant vanguard permis règles snap tap riot"},title:{en:"Is the Aim Trainer safe to use with Valorant?",fr:"L'entraîneur de visée est-il sans risque avec Valorant?"},body:[{p:{en:"The app only reads: the official Riot API and your own running client, like public rank trackers. It never touches the game.",fr:"L'application ne fait que lire : l'API officielle de Riot et votre propre client en cours d'exécution, comme les sites de classement publics. Elle ne touche jamais au jeu."}},{note:{en:"One optional setting, Snap Tap, breaks Valorant's rules. It is clearly labelled and off by default. Leave it off when you play Valorant.",fr:"Un seul réglage facultatif, Snap Tap, enfreint les règles de Valorant. Il est clairement indiqué et désactivé par défaut. Laissez-le désactivé quand vous jouez à Valorant."}},{link:["/valorant",{en:"About the Aim Trainer",fr:"À propos de l'entraîneur de visée"}]}]},{id:"aim-install",topic:"aim",keywords:{en:"install download aim trainer windows setup riot account stats",fr:"installer télécharger entraîneur de visée windows compte riot statistiques"},title:{en:"Installing the Aim Trainer",fr:"Installer l'entraîneur de visée"},body:[{p:{en:"The Aim Trainer is a free Windows app.",fr:"L'entraîneur de visée est une application Windows gratuite."}},{steps:{en:["Download it from the Aim Trainer page.","Run the installer.","Sign in through your browser with your Bazinet account (password, 2FA, passkey or Google). Your match stats come from the official Riot API."],fr:["Téléchargez-le à partir de la page de l'entraîneur de visée.","Lancez le programme d'installation.","Connectez-vous dans votre navigateur avec votre compte Bazinet (mot de passe, 2FA, clé d'accès ou Google). Les statistiques de vos parties viennent de l'API officielle de Riot."]}},{note:{en:"The app updates itself. If it ever says an update is required, let it install, then open it again.",fr:"L'application se met à jour d'elle-même. Si elle indique qu'une mise à jour est requise, laissez-la s'installer, puis rouvrez-la."}},{link:["/valorant/download",{en:"Download for Windows",fr:"Télécharger pour Windows"}]}]},{id:"two-step",topic:"account",popular:true,keywords:{en:"two factor 2fa authenticator app passkey fingerprint face security sign in code",fr:"deux étapes 2fa application d'authentification clé d'accès empreinte visage sécurité code"},title:{en:"Two-step sign-in and passkeys",fr:"Connexion en deux étapes et clés d'accès"},body:[{p:{en:"Every Bazinet account uses a second step at sign-in: a code sent by email, or an authenticator app. You can also add a passkey to sign in with your fingerprint, face or device PIN.",fr:"Chaque compte Bazinet utilise une deuxième étape à la connexion : un code envoyé par courriel ou une application d'authentification. Vous pouvez aussi ajouter une clé d'accès pour vous connecter avec votre empreinte, votre visage ou le NIP de votre appareil."}},{steps:{en:["Open your account page.","Under security, set up an authenticator app or add a passkey.","Keep your recovery options up to date."],fr:["Ouvrez la page de votre compte.","Dans la section sécurité, configurez une application d'authentification ou ajoutez une clé d'accès.","Gardez vos options de récupération à jour."]}},{link:["/account",{en:"Open my account",fr:"Ouvrir mon compte"}]}]},{id:"cant-sign-in",topic:"account",keywords:{en:"can't sign in login problem email code not received didn't get code didnt get the code never got the code no code arrived notreceived forgot account password signed out",fr:"impossible de se connecter code courriel pas reçu reçois recois reçu jamais reçu le code notreceived mot de passe du compte oublié déconnecté"},title:{en:"I can't sign in",fr:"Je n'arrive pas à me connecter"},body:[{steps:{en:["Check that you're using the email address you signed up with.","Forgot your account password? Use “Forgot password” on the sign-in page. This does not affect your vault.","Didn't get the email code? It comes from noreply@bazinet.net: check your spam folder, then ask for a new one after a minute.","Signed out on another device? Free accounts can use one device at a time; Pro allows several."],fr:["Vérifiez que vous utilisez l'adresse courriel avec laquelle vous vous êtes inscrit.","Mot de passe du compte oublié? Utilisez « Mot de passe oublié » sur la page de connexion. Cela ne touche pas votre coffre-fort.","Vous n'avez pas reçu le code par courriel? Il vient de noreply@bazinet.net : vérifiez vos courriels indésirables, puis demandez-en un nouveau après une minute.","Déconnecté sur un autre appareil? Les comptes gratuits permettent un appareil à la fois; Pro en permet plusieurs."]}},{note:{en:"You don't need to be signed in to contact us: open a request below with your email address.",fr:"Pas besoin d'être connecté pour nous joindre : ouvrez une demande ci-dessous avec votre adresse courriel."}}]},{id:"delete-account",topic:"account",keywords:{en:"delete close remove account erase data",fr:"supprimer fermer effacer compte données"},title:{en:"Deleting your account",fr:"Supprimer votre compte"},body:[{p:{en:"Deleting your account removes your vault, your Horaire agenda, your Omnivox connection and your support conversations. It can't be undone.",fr:"Supprimer votre compte efface votre coffre-fort, votre agenda Horaire, votre connexion Omnivox et vos conversations avec le soutien. C'est irréversible."}},{steps:{en:["Make an encrypted backup of anything you want to keep first (Vault settings → Backup & transfer).","Open your account page and choose “Delete my account”, then confirm with your password."],fr:["Faites d'abord une sauvegarde chiffrée de ce que vous voulez conserver (Paramètres du coffre-fort → Sauvegarde et transfert).","Ouvrez la page de votre compte, choisissez « Supprimer mon compte », puis confirmez avec votre mot de passe."]}},{note:{en:"A Pro subscription is cancelled at once, before anything is deleted, so you are not billed again. If it can't be cancelled, the account is not deleted and you're told so. Copies in our backups are gone within 31 days.",fr:"Un abonnement Pro est annulé immédiatement, avant toute suppression, pour que vous ne soyez plus facturé. S'il ne peut pas être annulé, le compte n'est pas supprimé et vous en êtes avisé. Les copies dans nos sauvegardes disparaissent dans les 31 jours."}},{link:["/account",{en:"Open my account",fr:"Ouvrir mon compte"}]}]},{id:"term-pass",topic:"billing",keywords:{en:"term pass session semester student one payment no subscription cheap december june renew",fr:"passe session semestre étudiant un paiement sans abonnement décembre juin renouveler"},title:{en:"The term pass",fr:"Le passe de session"},body:[{p:{en:"The term pass is Pro for one payment of $9.99, with no subscription and nothing to cancel. Bought between July and December, it lasts until December 31. Bought between January and June, it lasts until June 30.",fr:"Le passe de session, c'est Pro pour un seul paiement de 9,99 $, sans abonnement et sans rien à annuler. Acheté entre juillet et décembre, il dure jusqu'au 31 décembre. Acheté entre janvier et juin, il dure jusqu'au 30 juin."}},{p:{en:"In the last 30 days of a pass, you can buy the next one from your account; it covers the following term. When a pass ends and you haven't bought another, your account simply goes back to Free. Nothing is deleted.",fr:"Dans les 30 derniers jours d'un passe, vous pouvez acheter le suivant depuis votre compte; il couvre la session suivante. Quand un passe se termine sans être renouvelé, votre compte revient simplement à la formule gratuite. Rien n'est supprimé."}},{link:["/account#plan",{en:"See my plan",fr:"Voir mon forfait"}]}]},{id:"family",topic:"billing",keywords:{en:"family plan share invite members household kids partner shared vault 5 people",fr:"forfait famille partager inviter membres ménage enfants conjoint coffre partagé 5 personnes"},title:{en:"The Family plan",fr:"Le forfait Famille"},body:[{p:{en:"Family is $5.99 a month or $59.99 a year, with a 7-day free trial. The person who pays can invite up to 4 more people by email, and everyone in the family gets Pro at no cost to them.",fr:"Famille coûte 5,99 $ par mois ou 59,99 $ par année, avec 7 jours gratuits. La personne qui paie peut inviter jusqu'à 4 personnes par courriel, et toute la famille a Pro sans frais pour elle."}},{p:{en:"To join, open the invite email and accept it while signed in to the Bazinet account with that same address. You can leave a family at any time from Plan & billing; the person who pays can also remove you.",fr:"Pour rejoindre, ouvrez le courriel d'invitation et acceptez-le en étant connecté au compte Bazinet de cette même adresse. Vous pouvez quitter une famille en tout temps depuis Forfait et facturation; la personne qui paie peut aussi vous retirer."}},{p:{en:"Members share a family vault in Bazinet Vault, for passwords everyone needs. It is encrypted on your devices like your own vault: Bazinet can't read it. Your personal vault stays private: nobody in the family can see it.",fr:"Les membres partagent un coffre familial dans Bazinet Vault, pour les mots de passe dont tout le monde a besoin. Il est chiffré sur vos appareils comme votre propre coffre : Bazinet ne peut pas le lire. Votre coffre personnel reste privé : personne dans la famille ne peut le voir."}},{p:{en:"If the plan ends, everyone goes back to Free and the family vault becomes read-only, so nobody loses the passwords in it.",fr:"Si le forfait se termine, tout le monde revient à la formule gratuite et le coffre familial passe en lecture seule, pour que personne ne perde les mots de passe qu'il contient."}},{link:["/account#plan",{en:"See my plan",fr:"Voir mon forfait"}]}]},{id:"pro",topic:"billing",popular:true,keywords:{en:"price cost how much included features what do I get free plan paid premium trial",fr:"prix coût combien inclus fonctionnalités gratuit payant premium essai avantages"},title:{en:"Free vs Pro",fr:"Gratuit ou Pro"},body:[{p:{en:"Every tool is free to use. Pro covers the parts that cost money to run, and comes four ways: $2.99 a month or $24.99 a year (both with a 7-day free trial), a $9.99 term pass, or Family at $5.99 a month for up to 5 people.",fr:"Tous les outils sont gratuits. Pro paie ce qui coûte de l'argent à faire fonctionner, et se prend de quatre façons : 2,99 $ par mois ou 24,99 $ par année (avec 7 jours gratuits), un passe de session à 9,99 $, ou Famille à 5,99 $ par mois pour jusqu'à 5 personnes."}},{p:{en:"Vault with Pro: more than one device, built-in 2FA codes, encrypted notes and file attachments, full breach scans, email aliases and emergency access. Horaire with Pro: the Omnivox sign-in, Mio, cancelled classes, dates from your plans de cours, and sharing your schedule.",fr:"Coffre-fort avec Pro : plus d'un appareil, les codes 2FA intégrés, les notes et pièces jointes chiffrées, l'analyse complète des fuites, les alias courriel et l'accès d'urgence. Horaire avec Pro : la connexion Omnivox, Mio, les cours annulés, les dates de vos plans de cours et le partage de votre horaire."}},{link:["/account#plan",{en:"See my plan",fr:"Voir mon forfait"}]}]},{id:"cancel-pro",topic:"billing",keywords:{en:"cancel stop subscription refund refunds get a refund money back refund policy payment method card billing portal change plan",fr:"annuler arrêter abonnement remboursement rembourser ravoir mon argent mode de paiement carte facturation changer forfait"},title:{en:"Cancelling or changing Pro",fr:"Annuler ou modifier Pro"},body:[{steps:{en:["Open your account page and go to Plan & billing.","Choose “Manage subscription”.","Cancel, or update your payment method, in the billing page that opens."],fr:["Ouvrez la page de votre compte et allez à Forfait et facturation.","Choisissez « Gérer l'abonnement ».","Annulez, ou mettez à jour votre mode de paiement, dans la page de facturation qui s'ouvre."]}},{note:{en:"Cancel during the 7-day trial and you won't be charged.",fr:"Annulez pendant l'essai de 7 jours et vous ne serez pas facturé."}},{link:["/account#plan",{en:"Manage my plan",fr:"Gérer mon forfait"}]}]},{id:"support-access",topic:"privacy",popular:true,keywords:{en:"can support see read my passwords vault access log privacy staff can you read my vault can you see my data look inside",fr:"le soutien peut-il voir lire mes mots de passe coffre-fort accès journal confidentialité personnel"},title:{en:"What support can and cannot see",fr:"Ce que le soutien peut voir, et ne peut pas voir"},body:[{p:{en:"Your vault and your Horaire agenda are encrypted on your device. Support cannot read them, with or without your permission.",fr:"Votre coffre-fort et votre agenda Horaire sont chiffrés sur votre appareil. Le soutien ne peut pas les lire, avec ou sans votre permission."}},{p:{en:"To look into a problem, support can ask to read your account's activity log. You get an email with a link to approve or refuse it; access ends by itself, and you can end it sooner from your account page. Every read is recorded in your account history.",fr:"Pour examiner un problème, le soutien peut demander à lire le journal d'activité de votre compte. Vous recevez un courriel avec un lien pour l'accepter ou la refuser; l'accès prend fin de lui-même, et vous pouvez y mettre fin plus tôt à partir de la page de votre compte. Chaque lecture est inscrite dans l'historique de votre compte."}},{note:{en:"We will never ask for your password, your master password or your recovery key. Anyone who does is not us.",fr:"Nous ne vous demanderons jamais votre mot de passe, votre mot de passe maître ni votre clé de récupération. Quiconque le fait n'est pas nous."}}]},{id:"send-files",topic:"privacy",keywords:{en:"attach file screenshot photo picture image send upload pdf log iphone heic attachment",fr:"joindre fichier capture d'écran photo image envoyer téléverser pdf journal iphone heic pièce jointe"},title:{en:"Sending a screenshot or file to support",fr:"Envoyer une capture d'écran ou un fichier au soutien"},body:[{p:{en:"In a chat or a request, press the paperclip button next to the message box to attach a file. Each file appears in the conversation as its own message.",fr:"Dans un clavardage ou une demande, appuyez sur le bouton trombone à côté de la zone de message pour joindre un fichier. Chaque fichier apparaît dans la conversation comme un message distinct."}},{steps:{en:["Photos and screenshots: PNG, JPEG, or iPhone photos (HEIC).","Documents: PDF.","Logs: plain-text .txt, .log or .csv files.","Up to 10 MB per file."],fr:["Photos et captures d'écran : PNG, JPEG ou photos d'iPhone (HEIC).","Documents : PDF.","Journaux : fichiers texte .txt, .log ou .csv.","Jusqu'à 10 Mo par fichier."]}},{note:{en:"Other kinds of files (programs, archives, Office documents) can't be sent. Every file is checked for threats before our team opens it. Only the support team can see what you attach — never send a password, a recovery key or a verification code, in a file or a message.",fr:"Les autres types de fichiers (programmes, archives, documents Office) ne peuvent pas être envoyés. Chaque fichier est vérifié avant que notre équipe l'ouvre. Seule l'équipe de soutien voit ce que vous joignez — n'envoyez jamais de mot de passe, de clé de récupération ni de code de vérification, ni dans un fichier ni dans un message."}}]},{id:"security-report",topic:"privacy",keywords:{en:"vulnerability security bug report hack exploit disclosure",fr:"vulnérabilité sécurité faille signaler piratage divulgation"},title:{en:"Reporting a security issue",fr:"Signaler un problème de sécurité"},body:[{p:{en:"Found a vulnerability? Email support@bazinet.net with SECURITY in the subject. Please don't post it publicly. Include what you did, what happened and what you expected; a rough report now beats a polished one later.",fr:"Vous avez trouvé une vulnérabilité? Écrivez à support@bazinet.net en indiquant SECURITY dans l'objet. Ne la publiez pas. Indiquez ce que vous avez fait, ce qui s'est passé et ce que vous attendiez; un rapport sommaire maintenant vaut mieux qu'un rapport parfait plus tard."}},{p:{en:"We acknowledge security reports within 3 business days and coordinate disclosure with you.",fr:"Nous accusons réception des signalements de sécurité en 3 jours ouvrables et coordonnons la divulgation avec vous."}}]},{id:"privacy-request",topic:"privacy",keywords:{en:"personal data copy export delete law 25 privacy request information",fr:"données personnelles copie exporter supprimer loi 25 demande renseignements"},title:{en:"Accessing or deleting your personal information",fr:"Accéder à vos renseignements personnels ou les supprimer"},body:[{p:{en:"Under Québec's Law 25, you can ask to see, correct, delete or take a copy of the personal information we hold about you. We answer within 30 days.",fr:"En vertu de la Loi 25 du Québec, vous pouvez demander à consulter, corriger, supprimer ou obtenir une copie des renseignements personnels que nous détenons à votre sujet. Nous répondons dans un délai de 30 jours."}},{p:{en:"Open a request below and choose “Privacy and security”, or email support@bazinet.net.",fr:"Ouvrez une demande ci-dessous en choisissant « Confidentialité et sécurité », ou écrivez à support@bazinet.net."}},{link:["/privacy.html",{en:"Privacy policy",fr:"Politique de confidentialité"}]}]},{id:"vault-backup",topic:"vault",keywords:{en:"backup export import restore copy move transfer nordpass json csv file save my passwords switch from another password manager plaintext",fr:"sauvegarde exporter importer restaurer copie transférer nordpass json csv fichier changer de gestionnaire de mots de passe texte clair"},title:{en:"Backing up, exporting and importing your vault",fr:"Sauvegarder, exporter et importer votre coffre-fort"},body:[{p:{en:"Everything that moves data in or out of the vault is in Vault settings, under Backup & transfer.",fr:"Tout ce qui fait entrer ou sortir des données du coffre-fort se trouve dans Paramètres du coffre-fort, sous Sauvegarde et transfert."}},{steps:{en:["Encrypted backup (recommended): a file only your backup passphrase can open, separate from your master password.","Restore from backup: reads the entries of an encrypted backup back in.","Import from JSON or from NordPass (CSV): brings in entries from another password manager's export.","Export as plaintext (JSON): every password in readable text. Only if you really need it, and delete the file afterwards."],fr:["Sauvegarde chiffrée (recommandée) : un fichier que seule votre phrase de passe de sauvegarde peut ouvrir, distincte de votre mot de passe maître.","Restaurer depuis une sauvegarde : relit les entrées d'une sauvegarde chiffrée.","Importer depuis JSON ou depuis NordPass (CSV) : récupère les entrées exportées d'un autre gestionnaire de mots de passe.","Exporter en texte clair (JSON) : tous les mots de passe en texte lisible. Seulement si vous en avez vraiment besoin, et supprimez le fichier ensuite."]}},{note:{en:"A backup lives only where you save it. We can't recover a lost backup passphrase.",fr:"Une sauvegarde n'existe que là où vous l'enregistrez. Nous ne pouvons pas récupérer une phrase de passe de sauvegarde perdue."}},{link:["/app",{en:"Open the vault",fr:"Ouvrir le coffre-fort"}]}]},{id:"change-master",topic:"vault",keywords:{en:"change master password new master password rotate vault key re-encrypt compromised recovery key generate",fr:"changer mot de passe maître nouveau renouveler clé du coffre rechiffrer compromis générer clé de récupération"},title:{en:"Changing your master password or recovery key",fr:"Changer votre mot de passe maître ou votre clé de récupération"},body:[{p:{en:"These are in Vault settings, under Security. You need to know your current master password (or use your recovery key).",fr:"Ces options se trouvent dans Paramètres du coffre-fort, sous Sécurité. Il vous faut votre mot de passe maître actuel (ou votre clé de récupération)."}},{steps:{en:["Change master password: re-locks the vault under a new password. Your entries are not re-encrypted.","Recovery key: makes a new key. It is shown only once, so save it right away; the old one stops working.","Rotate vault key: replaces the encryption key itself and re-encrypts every entry. Use it if you think someone may have had your old key."],fr:["Changer le mot de passe maître : reverrouille le coffre-fort avec un nouveau mot de passe. Vos entrées ne sont pas rechiffrées.","Clé de récupération : crée une nouvelle clé. Elle n'est affichée qu'une fois, alors enregistrez-la tout de suite; l'ancienne cesse de fonctionner.","Renouveler la clé du coffre-fort : remplace la clé de chiffrement elle-même et rechiffre chaque entrée. Utilisez-la si vous pensez que quelqu'un a pu avoir votre ancienne clé."]}},{note:{en:"Your account password (for signing in) is separate, and is changed from your account page.",fr:"Le mot de passe de votre compte (pour vous connecter) est distinct et se change à partir de la page de votre compte."}}]},{id:"attachments",topic:"vault",keywords:{en:"attach file to entry attachment attachments document pdf image upload size limit how big large maximum vault files",fr:"joindre fichier à une entrée pièce jointe pièces jointes document pdf image téléverser taille limite grosseur maximum fichiers du coffre"},title:{en:"Files in your vault",fr:"Des fichiers dans votre coffre-fort"},body:[{p:{en:"With Pro, you can attach files to vault entries, such as a scan of a document or a backup code sheet. They are encrypted on your device like the rest of your vault; we only ever store the encrypted file.",fr:"Avec Pro, vous pouvez joindre des fichiers à vos entrées, comme la numérisation d'un document ou une feuille de codes de secours. Ils sont chiffrés sur votre appareil comme le reste du coffre-fort; nous ne conservons que le fichier chiffré."}},{steps:{en:["Up to 10 files per account.","Up to 512 KB per file.","If Pro ends, you can still open and download the files you have; adding new ones needs Pro."],fr:["Jusqu'à 10 fichiers par compte.","Jusqu'à 512 Ko par fichier.","Si Pro se termine, vous pouvez toujours ouvrir et télécharger vos fichiers; en ajouter de nouveaux exige Pro."]}}]},{id:"aliases",topic:"vault",keywords:{en:"email alias masked email hide my email forwarding address spam sign up newsletter vault- address",fr:"alias courriel adresse masquée cacher mon courriel transfert adresse pourriel inscription infolettre adresse vault-"},title:{en:"Email aliases",fr:"Alias de courriel"},body:[{p:{en:"An email alias is a masked vault-… address that forwards to your real inbox (Pro). Give it out instead of your own email when you sign up somewhere, and turn it off if it starts getting spam.",fr:"Un alias de courriel est une adresse masquée vault-… qui transfère vers votre vraie boîte de réception (Pro). Donnez-la au lieu de votre courriel quand vous vous inscrivez quelque part, et désactivez-la si elle se met à recevoir du pourriel."}},{steps:{en:["In the vault, open Email aliases.","Choose Create alias, and give it a label so you remember where you used it.","The first time, confirm your real address from the verification email, so forwarded mail can reach you."],fr:["Dans le coffre-fort, ouvrez Alias de courriel.","Choisissez Créer un alias et donnez-lui une étiquette pour vous rappeler où vous l'avez utilisé.","La première fois, confirmez votre vraie adresse à partir du courriel de vérification, pour que le courrier transféré puisse vous parvenir."]}},{note:{en:"Up to 10 aliases per account. Forwarded mail is not stored. If you reply to a forwarded message, the reply comes from your real address.",fr:"Jusqu'à 10 alias par compte. Le courrier transféré n'est pas conservé. Si vous répondez à un message transféré, la réponse part de votre vraie adresse."}}]},{id:"emergency-access",topic:"vault",keywords:{en:"emergency access trusted contact if I die inheritance someone access my vault waiting period grant",fr:"accès d'urgence personne de confiance si je meurs héritage accéder à mon coffre délai d'attente"},title:{en:"Emergency access",fr:"Accès d'urgence"},body:[{p:{en:"With Pro, you can let a trusted person reach your vault if you can't, but only after a waiting period you choose (1 to 30 days), during which you can decline.",fr:"Avec Pro, vous pouvez permettre à une personne de confiance d'accéder à votre coffre-fort si vous ne le pouvez pas, mais seulement après un délai d'attente que vous choisissez (1 à 30 jours), pendant lequel vous pouvez refuser."}},{steps:{en:["In the vault, open Emergency access and invite the person by email. They need their own Bazinet account.","When they accept, check their key with them and finish adding them.","If they ever request access, you get an email at once. Approve it, decline it, or do nothing: access opens when the waiting period ends, and you are both emailed."],fr:["Dans le coffre-fort, ouvrez Accès d'urgence et invitez la personne par courriel. Elle doit avoir son propre compte Bazinet.","Quand elle accepte, vérifiez sa clé avec elle et terminez l'ajout.","Si elle demande un jour l'accès, vous recevez un courriel tout de suite. Acceptez, refusez ou ne faites rien : l'accès s'ouvre à la fin du délai d'attente, et vous recevez tous les deux un courriel."]}},{note:{en:"Once access has been used, it can't be undone. You can remove a contact at any time before that.",fr:"Une fois l'accès utilisé, c'est irréversible. Vous pouvez retirer une personne en tout temps avant cela."}}]},{id:"missions",topic:"vault",keywords:{en:"mission mode travel border crossing journalist separate passcode code temporary expire destroy few entries open without account",fr:"mode mission voyage frontière journaliste code d'accès distinct code temporaire expire détruire quelques entrées ouvrir sans compte"},title:{en:"Mission Mode",fr:"Mode Mission"},body:[{p:{en:"Mission Mode puts a few entries under their own lock for a trip, a border crossing or a sensitive meeting. You open a mission at bazinet.net/mission with its mission code and its passcode: no account, no master password, and nothing on that device shows that a full vault exists.",fr:"Le Mode Mission place quelques entrées sous leur propre verrou pour un voyage, un passage de frontière ou une rencontre délicate. Vous ouvrez une mission sur bazinet.net/mission avec son code de mission et son code d'accès : aucun compte, aucun mot de passe maître, et rien sur cet appareil ne montre qu'un coffre-fort complet existe."}},{steps:{en:["In the vault, open Mission Mode and choose New mission.","Pick the entries, how long it lasts (up to 30 days) and how many wrong passcodes destroy it.","Choose a passcode, then write down the mission code it shows you.","On the trip, go to bazinet.net/mission and enter the code and the passcode."],fr:["Dans le coffre-fort, ouvrez Mode Mission et choisissez Nouvelle mission.","Choisissez les entrées, sa durée (jusqu'à 30 jours) et le nombre de codes d'accès erronés qui la détruisent.","Choisissez un code d'accès, puis notez le code de mission affiché.","En voyage, allez sur bazinet.net/mission et entrez le code et le code d'accès."]}},{p:{en:"From the vault you can see a mission's code again, change its entries, extend it, or delete it. An open mission closes after 5 minutes without use.",fr:"Depuis le coffre-fort, vous pouvez revoir le code d'une mission, changer ses entrées, la prolonger ou la supprimer. Une mission ouverte se ferme après 5 minutes sans utilisation."}},{note:{en:"When a mission ends, or too many wrong passcodes are entered, it is deleted from our servers. A lost passcode can't be recovered: delete the mission and make a new one. Your vault itself is never affected.",fr:"Quand une mission prend fin, ou après trop de codes d'accès erronés, elle est supprimée de nos serveurs. Un code d'accès perdu ne peut pas être récupéré : supprimez la mission et créez-en une nouvelle. Votre coffre-fort lui-même n'est jamais touché."}}]},{id:"breach-check",topic:"privacy",keywords:{en:"breach check leaked password pwned have i been pwned data breach compromised password health weak reused",fr:"vérification des fuites mot de passe divulgué pwned fuite de données compromis santé des mots de passe faible réutilisé"},title:{en:"Checking whether a password has leaked",fr:"Vérifier si un mot de passe a fuité"},body:[{p:{en:"The breach check compares a password with the leaks collected by Have I Been Pwned without ever sending it: only the first five characters of its hash leave your device, and nothing is stored.",fr:"La vérification des fuites compare un mot de passe aux fuites répertoriées par Have I Been Pwned sans jamais l'envoyer : seuls les cinq premiers caractères de son hachage quittent votre appareil, et rien n'est conservé."}},{steps:{en:["Check one password at a time on the Breach check page, for free.","With Pro, Password health in the vault checks every entry at once and flags weak and reused passwords too.","Change any password that shows up in a leak, starting with your email and banking."],fr:["Vérifiez un mot de passe à la fois sur la page Vérification des fuites, gratuitement.","Avec Pro, Santé des mots de passe dans le coffre-fort vérifie toutes les entrées d'un coup et signale aussi les mots de passe faibles et réutilisés.","Changez tout mot de passe qui apparaît dans une fuite, en commençant par votre courriel et vos services bancaires."]}},{link:["/breach.html",{en:"Open the breach check",fr:"Ouvrir la vérification des fuites"}]}]},{id:"horaire-signin-again",topic:"horaire",keywords:{en:"sign in to omnivox again session ended expired code email cancelled classes not checked reconnect omnivox code expired omnivox code notreceived",fr:"reconnectez-vous à omnivox session terminée expirée code courriel cours annulés non vérifiés reconnecter code expiré code omnivox notreceived"},title:{en:"Horaire asks me to sign in to Omnivox again",fr:"Horaire me demande de me reconnecter à Omnivox"},body:[{p:{en:"Omnivox ends sessions on its own from time to time. Horaire first tries to sign back in quietly with your remembered device. When that isn't enough, it shows “Sign in to Omnivox again” and waits for you: it never makes Omnivox email you a code by itself.",fr:"Omnivox met fin aux sessions de lui-même de temps en temps. Horaire essaie d'abord de se reconnecter discrètement avec votre appareil mémorisé. Quand ça ne suffit pas, il affiche « Reconnectez-vous à Omnivox » et vous attend : il ne fait jamais envoyer de code par Omnivox de lui-même."}},{steps:{en:["When you can check your email, choose “Sign in now”.","Omnivox may email you a code: enter it in Horaire within a few minutes.","Horaire syncs again, and the device is remembered."],fr:["Quand vous pouvez consulter vos courriels, choisissez « Me connecter maintenant ».","Omnivox peut vous envoyer un code par courriel : entrez-le dans Horaire en quelques minutes.","Horaire se synchronise de nouveau, et l'appareil est mémorisé."]}},{note:{en:"If the code is refused, ask for a new one rather than retrying the old one: each code only works once and for a short time.",fr:"Si le code est refusé, demandez-en un nouveau plutôt que de réessayer l'ancien : chaque code ne fonctionne qu'une fois et pour peu de temps."}}]},{id:"horaire-share",topic:"horaire",keywords:{en:"share schedule timetable with parent friend classmate partner invite view edit tasks shared with me",fr:"partager horaire avec parent ami camarade inviter consulter modifier tâches partagé avec moi"},title:{en:"Sharing your schedule",fr:"Partager votre horaire"},body:[{p:{en:"With Horaire Pro, you can share your schedule with up to 10 people. They see your timetable and tasks, updated live. Your Omnivox sign-in, your name and your DA are never shared, and the copy they get is encrypted end to end.",fr:"Avec Horaire Pro, vous pouvez partager votre horaire avec jusqu'à 10 personnes. Elles voient votre horaire et vos tâches, mis à jour en direct. Votre connexion Omnivox, votre nom et votre DA ne sont jamais partagés, et la copie qu'elles reçoivent est chiffrée de bout en bout."}},{steps:{en:["In Horaire, open the menu, then Share and shared schedules.","Enter the person's email and choose Can view or Can edit tasks, then Share.","They open it under Shared with you, with their own free Bazinet account."],fr:["Dans Horaire, ouvrez le menu, puis Partage et horaires partagés.","Entrez le courriel de la personne et choisissez Peut consulter ou Peut modifier les tâches, puis Partager.","Elle l'ouvre sous Partagés avec vous, avec son propre compte Bazinet gratuit."]}},{note:{en:"You can change someone's permission or stop sharing at any time. If your Pro ends, sharing pauses until you renew.",fr:"Vous pouvez changer la permission d'une personne ou cesser de partager en tout temps. Si votre Pro se termine, le partage est suspendu jusqu'au renouvellement."}}]},{id:"horaire-cancelled",topic:"horaire",keywords:{en:"cancelled class canceled course teacher absent crossed out not checked notification today class cancelled",fr:"cours annulé annulation enseignant absent barré non vérifié aujourd'hui cours annulés"},title:{en:"Cancelled classes",fr:"Les cours annulés"},body:[{p:{en:"With Horaire Pro, a class that is cancelled in Omnivox shows crossed out in your week, with the teacher's note, so you know before you leave home.",fr:"Avec Horaire Pro, un cours annulé dans Omnivox apparaît barré dans votre semaine, avec la note de l'enseignant, pour que vous le sachiez avant de partir."}},{p:{en:"Horaire needs to reach Omnivox to see cancellations: through the browser extension on a computer, or your Omnivox connection on a phone. If it says cancelled classes are not being checked, choose the sign-in it offers.",fr:"Horaire doit pouvoir joindre Omnivox pour voir les annulations : avec l'extension de navigateur sur un ordinateur, ou votre connexion Omnivox sur un téléphone. S'il indique que les cours annulés ne sont pas vérifiés, choisissez la connexion qu'il propose."}},{note:{en:"Always trust Omnivox over Horaire for something important: Horaire shows what Omnivox says, a little later.",fr:"Fiez-vous toujours à Omnivox plutôt qu'à Horaire pour quelque chose d'important : Horaire affiche ce qu'Omnivox indique, un peu plus tard."}}]},{id:"emails-from-us",topic:"account",keywords:{en:"email from bazinet noreply no-reply phishing fake email is this real which address do you send from reply",fr:"courriel de bazinet noreply hameçonnage faux courriel est-ce vrai quelle adresse répondre"},title:{en:"Emails from Bazinet",fr:"Les courriels de Bazinet"},body:[{p:{en:"Automated emails (sign-in codes, security notices, receipts, reminders) come from noreply@bazinet.net. That address doesn't accept mail: emails about a support request let you reply to support@bazinet.net instead.",fr:"Les courriels automatiques (codes de connexion, avis de sécurité, reçus, rappels) viennent de noreply@bazinet.net. Cette adresse n'accepte pas de courrier : les courriels liés à une demande de soutien vous permettent plutôt de répondre à support@bazinet.net."}},{note:{en:"We will never ask for your password, your master password or your recovery key, by email or anywhere else. Links in our emails always go to bazinet.net. If you're unsure about an email, don't click it: open a request here.",fr:"Nous ne vous demanderons jamais votre mot de passe, votre mot de passe maître ni votre clé de récupération, par courriel ou ailleurs. Les liens de nos courriels mènent toujours à bazinet.net. En cas de doute sur un courriel, ne cliquez pas : ouvrez une demande ici."}}]},{id:"how-support-works",topic:"account",keywords:{en:"contact support how long reply response time live chat person human ticket bazinet ai assistant hours",fr:"joindre le soutien délai de réponse clavardage personne humain demande assistant bazinet ai heures"},title:{en:"How support works",fr:"Comment fonctionne le soutien"},body:[{p:{en:"In a live chat, Bazinet AI answers first from these help articles; it never makes anything up. Tap “Contact support” at any time to reach a person.",fr:"Dans un clavardage, Bazinet AI répond d'abord à partir de ces articles d'aide; il n'invente jamais rien. Touchez « Joindre le soutien » en tout temps pour parler à une personne."}},{steps:{en:["Live chat: a person answers right away when someone is online; otherwise the conversation continues here and by email.","A written request: usually answered within one business day.","Security reports: acknowledged within 3 business days."],fr:["Clavardage : une personne répond tout de suite si quelqu'un est en ligne; sinon la conversation se poursuit ici et par courriel.","Une demande écrite : réponse habituellement en un jour ouvrable.","Signalements de sécurité : accusé de réception en 3 jours ouvrables."]}},{note:{en:"You don't need an account to contact us. Never share a password, master password, recovery key or code in a chat.",fr:"Pas besoin de compte pour nous joindre. Ne partagez jamais de mot de passe, de mot de passe maître, de clé de récupération ni de code dans un clavardage."}}]},{id:"status",topic:"account",keywords:{en:"outage outage not working site unavailable status page maintenance offline everything broken",fr:"panne panne ne fonctionne pas site indisponible page d'état maintenance hors ligne tout est brisé"},title:{en:"Is Bazinet down?",fr:"Bazinet est-il en panne?"},body:[{p:{en:"The status page shows whether each part of Bazinet is working, any planned maintenance, and incidents as they happen. It is checked every two minutes and runs separately from the rest of the site.",fr:"La page d'état indique si chaque partie de Bazinet fonctionne, les maintenances prévues et les incidents en cours. Elle est vérifiée aux deux minutes et fonctionne à part du reste du site."}},{p:{en:"If the status page says everything works but something fails for you, open a request here with what you see on screen.",fr:"Si la page d'état indique que tout fonctionne mais que quelque chose échoue chez vous, ouvrez une demande ici en décrivant ce que vous voyez à l'écran."}},{link:["https://status.bazinet.net/",{en:"Open the status page",fr:"Ouvrir la page d'état"}]}]}]})(typeof window!=="undefined"?window:globalThis);
